/* Crescendo — theory studies, part 2: units 5–8 (away from the piano) */
'use strict';

STUDIES.push(
  /* ===================== Unit 5: Chords ===================== */
  { id: 'th-intervals', u: 5, title: 'Intervals: counting the distance', mins: 6, sum: 'How to name the distance between two notes by counting letters, and how to spot each interval on the staff by its shape.', cards: [
    { t: 'text', h: 'Count the letters', p: ['An **interval** is the distance between two notes. To name it, count the **letter names** from the lower note to the higher one, including both ends. Ignore sharps and flats for now: only the letters count.', 'C up to E is C, D, E: three letters, so it’s a **3rd** ([[keys:C4 E4|C–E]]). C up to G is C, D, E, F, G: a **5th** ([[keys:C4 G4|C–G]]). Neighbouring letters make a **2nd**, and eight letters up, back to the same letter, is an **octave** ([[keys:C4 C5|C–C]]).', 'Two notes on exactly the same pitch are a **unison**.'] },
    { t: 'staff', h: 'Odd intervals: line to line, space to space', music: '[E4,G4]h [F4,A4]h | [E4,B4]h [F4,C5]h | [E4,D5]h [F4,E5]h', p: ['When both notes sit on lines, or both in spaces, the interval is odd. From one line to the next line up is a **3rd**, two lines up is a **5th**, and three lines up is a **7th**. Spaces work the same way. Tap a pair to hear it.'] },
    { t: 'staff', h: 'Even intervals: line to space', music: '[E4,F4]h [E4,A4]h | [E4,C5]h [E4,E5]h', p: ['When one note is on a line and the other is in a space, the interval is even: a **2nd**, **4th**, **6th** or **octave**. A 2nd is so close that its two notes are drawn side by side.'] },
    { t: 'quiz', q: 'What interval is this? Count the lines and spaces, including both notes.', staff: 'G4h E5h', opts: ['6th', '5th', '7th'], ans: 0, why: 'G is on a line and E is in a space, so the interval is even. G, A, B, C, D, E is six letters: a 6th.' },
    { t: 'text', h: 'Melodic or harmonic, up or down', p: ['When two notes sound **one after the other**, the interval is **melodic**, like the steps and leaps of a tune. When they sound **together**, it’s **harmonic**, part of a chord. Tap [[C4]] then [[E4]] for a melodic 3rd, or [[keys:C4 E4|C and E together]] for a harmonic one.', 'Intervals can go down as well as up, and the name stays the same: E down to C is still a 3rd.'] },
    { t: 'quiz', q: 'From F **down** to D is a…', opts: ['3rd', '2nd', '4th'], ans: 0, why: 'F, E, D is three letters, counting both ends, so it’s a 3rd. Intervals are named the same way going down.' },
    { t: 'quiz', q: 'Two notes played at the same time make a…', opts: ['Harmonic interval', 'Melodic interval'], ans: 0, why: 'Harmonic intervals sound together, like a chord. Melodic intervals sound one after the other, like a tune.' },
    { t: 'task', h: 'Try this now', steps: ['Write the letters C D E F G A B C D E F G across a piece of paper, so you can count past the octave.', 'Use them to name these intervals: C up to A, D up to A, F up to E and B up to D. Answers: 6th, 5th, 7th and 3rd.', 'Draw five lines for a staff. Write a note on the bottom line, then a 3rd, 5th and 7th above it: each top note should land on a line.', 'Now start in the bottom space and write a 2nd, 4th and 6th above it: these top notes should land on lines too.', 'Next time you hear a tune, notice whether it moves mostly by steps (2nds) or by leaps (3rds and wider).'] },
    { t: 'drill', h: 'Name the interval', spec: { k: 'intervals', names: true, count: 8 } },
  ] },
  { id: 'th-quality', u: 5, title: 'Major, minor and perfect intervals', mins: 7, sum: 'Why a 3rd can be major or minor, how to size any interval in {semis}, and songs that help you hear each one.', cards: [
    { t: 'text', h: 'Number and quality', p: ['The number (2nd, 3rd, 5th…) only counts letters. The **quality** gives the exact size, counted in {semis}: one {semi} is the step from one key to the very next, black or white.', 'C up to E and C up to E♭ are both 3rds, because both span the letters C, D, E. But C–E is 4 {semis}, a **major 3rd** ([[keys:C4 E4|C–E]]), while C–E♭ is only 3, a **minor 3rd** ([[keys:C4 Eb4|C–E♭]]).'] },
    { t: 'text', h: 'Perfect, major and minor', p: ['Unisons, 4ths, 5ths and octaves are called **perfect**. They sound so open and stable that they come in just one normal size.', '2nds, 3rds, 6ths and 7ths come in two sizes: the larger is **major**, and the one a {semi} smaller is **minor**.', 'Right in the middle sits the **tritone**, 6 {semis} (C up to F♯, or F up to B). It’s famously tense and restless.'] },
    { t: 'text', h: 'The {semi} count', p: ['Every interval from C, with its size in {semis}:', '- **Minor 2nd**: 1 (C–D♭)\n- **Major 2nd**: 2 (C–D)\n- **Minor 3rd**: 3 (C–E♭)\n- **Major 3rd**: 4 (C–E)\n- **Perfect 4th**: 5 (C–F)\n- **Tritone**: 6 (C–F♯)\n- **Perfect 5th**: 7 (C–G)\n- **Minor 6th**: 8 (C–A♭)\n- **Major 6th**: 9 (C–A)\n- **Minor 7th**: 10 (C–B♭)\n- **Major 7th**: 11 (C–B)\n- **Octave**: 12 (C–C)'] },
    { t: 'staff', h: 'Hear them all from C', music: '[C4,Db4]q [C4,D4]q [C4,Eb4]q [C4,E4]q | [C4,F4]q [C4,F#4]q [C4,G4]q [C4,Ab4]q | [C4,A4]q [C4,Bb4]q [C4,B4]q [C4,C5]q', p: ['Twelve intervals, each a {semi} wider than the last. Tap them one at a time: the minor ones sound softer and darker, the major ones brighter, and the perfect ones open and hollow.'] },
    { t: 'quiz', q: 'How many {semis} are there in a perfect 5th?', opts: ['7', '5', '8'], ans: 0, why: 'Count every key from C up to G, black and white: C♯, D, D♯, E, F, F♯, G. That’s 7 {semis}.' },
    { t: 'text', h: 'Songs that help you hear them', p: ['Each rising interval matches the start of a well-known tune (the first two notes, unless noted):', '- **Minor 2nd**: the *Jaws* theme\n- **Major 2nd**: “Frère Jacques”\n- **Minor 3rd**: “Greensleeves”\n- **Major 3rd**: “Oh When the Saints”\n- **Perfect 4th**: “Here Comes the Bride”\n- **Perfect 5th**: “Twinkle Twinkle Little Star”, 2nd to 3rd note\n- **Major 6th**: “My Bonnie Lies over the Ocean”\n- **Octave**: “Somewhere over the Rainbow”'] },
    { t: 'quiz', q: 'C up to A♭ is a…', opts: ['Minor 6th', 'Major 6th', 'Perfect 5th'], ans: 0, why: 'C to A is six letters, a 6th. C–A is a major 6th (9 {semis}), so C–A♭, a {semi} smaller, is a minor 6th (8).' },
    { t: 'quiz', q: 'Which of these intervals is **perfect**?', opts: ['A 4th', 'A 3rd', 'A 6th'], ans: 0, why: 'Unisons, 4ths, 5ths and octaves are perfect. 2nds, 3rds, 6ths and 7ths are major or minor.' },
    { t: 'task', h: 'Try this now', steps: ['Picture the keyboard and count the {semis} from D up to F and from D up to F♯. Decide which is minor and which is major, then check: D–F is 3, D–F♯ is 4.', 'Do the same from A, counting up to C and to C♯, and name both 3rds.', 'Write the twelve intervals and their {semi} counts on a card, then test yourself while you wait for a bus or the kettle.', 'Hum “Twinkle Twinkle”, then “Here Comes the Bride”. Notice that the 5th in “Twinkle” feels wider and more open than the 4th.'] },
    { t: 'drill', h: 'Name the quality', spec: { k: 'ivqual', set: ['M2', 'm3', 'M3', 'P4', 'P5', 'M6', 'P8'], count: 8 } },
  ] },
  { id: 'th-triads', u: 5, title: 'Triads: major, minor, diminished, augmented', mins: 7, sum: 'How three-note chords are built from stacked 3rds, and how the sizes of those 3rds make four different kinds of triad.', cards: [
    { t: 'text', h: 'Stacking 3rds', p: ['A **triad** is three notes stacked in 3rds. Start on any note, the **root**. Skip a letter to find the **3rd**, then skip another to find the **5th**. From C: C (skip D) E (skip F) G.', 'The 3rd and 5th are named for their distance above the root: E is a 3rd above C, and G is a 5th above it. On the staff, a root-position triad looks like a snowman: three lines in a row or three spaces in a row.'] },
    { t: 'staff', h: 'One root, four triads', music: '"C" [C4,E4,G4]h "Cm" [C4,Eb4,G4]h | "Cdim" [C4,Eb4,Gb4]h "Caug" [C4,E4,G#4]h', p: ['The same snowman shape gives four different sounds. Only the sizes of the 3rds change. Tap each chord and listen to its character.'] },
    { t: 'text', h: 'The four qualities', p: ['- **Major** = major 3rd + minor 3rd (4 + 3 {semis}): C E G. Bright and settled.\n- **Minor** = minor 3rd + major 3rd (3 + 4): C E♭ G. Darker, often sad or thoughtful.\n- **Diminished** = two minor 3rds (3 + 3): C E♭ G♭. Tense and unstable.\n- **Augmented** = two major 3rds (4 + 4): C E G♯. Dreamy and unsettled.', 'Major and minor triads both have a perfect 5th (7 {semis}) from root to top. Diminished shrinks it to 6; augmented stretches it to 8.'] },
    { t: 'quiz', q: 'Which notes make **A minor**?', opts: ['A C E', 'A C♯ E', 'A C E♭'], ans: 0, why: 'A to C is a minor 3rd (3 {semis}) and C to E is a major 3rd (4). A minor 3rd at the bottom makes the triad minor.' },
    { t: 'text', h: 'Building any triad', p: ['Here’s a reliable way to spell a triad on any root:', '- Write the letters, skipping one each time: D F A.\n- Count the {semis} in the bottom 3rd and fix it with a sharp or flat if needed.\n- Check the 5th: 7 {semis} for major and minor.', 'For **D major**, D–F is only 3 {semis}, a minor 3rd. Raise F to F♯ to make it a major 3rd: **D F♯ A**.'] },
    { t: 'quiz', q: 'D–F–A♭ is which kind of triad?', opts: ['Diminished', 'Minor', 'Augmented'], ans: 0, why: 'D to F is a minor 3rd (3 {semis}), and F to A♭ is another minor 3rd. Two minor 3rds make a diminished triad: Ddim.' },
    { t: 'quiz', q: 'How do you turn **G major** (G B D) into **G minor**?', opts: ['Lower B to B♭', 'Raise D to D♯', 'Lower G to G♭'], ans: 0, why: 'Minor puts the smaller 3rd at the bottom. Lowering the 3rd, B, by a {semi} gives G B♭ D: G minor.' },
    { t: 'task', h: 'Try this now', steps: ['Write a triad on every white note from C to B by skipping letters: C E G, D F A, E G B, and so on.', 'Count the {semis} in each bottom 3rd and label the triad major (4) or minor (3).', 'Check the 5th of the B triad (B D F): it’s only 6 {semis}, so that one is diminished. You should have three major, three minor and one diminished.', 'Turn C, F and G major into minor by lowering the middle note a {semi}: C E♭ G, F A♭ C and G B♭ D.', 'Spell C augmented and F augmented by raising the 5th of each major triad. Check: C E G♯ and F A C♯.'] },
    { t: 'drill', h: 'Spell the chord', spec: { k: 'chordspell', chords: ['C', 'F', 'G', 'Am', 'Dm', 'Em'], count: 8 } },
  ] },
  { id: 'th-symbols', u: 5, title: 'Reading chord symbols', mins: 7, sum: 'How to turn chord symbols such as Cm, G7, Fmaj7, Dsus4 and C/E into the right notes.', cards: [
    { t: 'text', h: 'Letters above the music', p: ['A **chord symbol** is shorthand for a chord. The capital letter is the **root**, and anything after it describes the type. A letter on its own means a major triad: **F** is F A C ([[chord:F]]).', 'A sharp or flat after the letter belongs to the root: **B♭** is B♭ D F ([[chord:Bb]]), and **F♯m** is F♯ minor, F♯ A C♯ ([[chord:F#m]]).'] },
    { t: 'text', h: 'Triad symbols', p: ['- **C**: major, C E G [[chord:C]]\n- **Cm**: minor, C E♭ G [[chord:Cm]]\n- **Cdim** or **C°**: diminished, C E♭ G♭ [[chord:Cdim]]\n- **Caug** or **C+**: augmented, C E G♯ [[chord:Caug]]\n- **Csus2**: C D G, with a 2nd instead of the 3rd [[chord:Csus2]]\n- **Csus4**: C F G, with a 4th instead of the 3rd [[chord:Csus4]]', 'You may also see minor written as **Cmin** or **Cmi**. It means the same thing.'] },
    { t: 'text', h: 'Seventh chord symbols', p: ['- **C7**: dominant 7th, C E G B♭ [[chord:C7]]\n- **Cmaj7**: major 7th, C E G B [[chord:Cmaj7]]\n- **Cm7**: minor 7th, C E♭ G B♭ [[chord:Cm7]]', 'Watch the difference: a plain **7** adds the note a {tone} below the root (B♭ for C), while **maj7** adds the note just a {semi} below it (B). Jazz charts sometimes write Cmaj7 as **CΔ**.'] },
    { t: 'quiz', q: 'Which notes make **G7**?', opts: ['G B D F', 'G B D F♯', 'G B♭ D F'], ans: 0, why: 'A plain 7 means a major triad (G B D) plus the note a {tone} below the root: F. That’s a dominant 7th.' },
    { t: 'text', h: 'Slash chords', p: ['A slash names the **bass note**, the lowest note. **C/E** is a C chord with E at the bottom ([[chord:C/E]]), and **G/B** is a G chord with B at the bottom.', 'Often the bass note belongs to the chord, which makes an inversion. Sometimes it doesn’t, as in **D/C**: a D chord over a C in the bass. Either way, the letter before the slash is the chord and the letter after it is the bass.'] },
    { t: 'text', h: 'From symbol to notes', p: ['Spell any symbol in four steps:', '- **Root**: the capital letter, with any ♯ or ♭.\n- **Triad**: major, unless there’s an m, dim, aug or sus.\n- **Extras**: add the 7th for 7, maj7 or m7.\n- **Bass**: if there’s a slash, put that note at the bottom.'] },
    { t: 'quiz', q: 'Which chord symbol means D F A C?', opts: ['Dm7', 'D7', 'Dmaj7'], ans: 0, why: 'D F A is D minor, and C is a {tone} below D, a minor 7th above it. A minor triad plus a minor 7th is a minor 7th chord: Dm7.' },
    { t: 'quiz', q: 'In **A/C♯**, which note is lowest?', opts: ['C♯', 'A', 'E'], ans: 0, why: 'The note after the slash is the bass. A/C♯ is an A major chord (A C♯ E) with C♯ at the bottom.' },
    { t: 'task', h: 'Try this now', steps: ['Spell these on paper without looking back: Fm, E7, B♭maj7, Dsus4 and C/G.', 'Check: F A♭ C; E G♯ B D; B♭ D F A; D G A; and C E G with G at the bottom.', 'Find the chords of a song you like, in a songbook or on a chord website, and list every different symbol.', 'Spell each one, root first, and circle any you weren’t sure about so you can look them up later.'] },
    { t: 'drill', h: 'Name the chord', spec: { k: 'chordname', chords: ['C', 'F', 'G', 'Am', 'Dm', 'Em', 'D', 'A', 'E'], count: 8 } },
  ] },
  { id: 'th-inversions', u: 5, title: 'Inversions: same chord, new shape', mins: 7, sum: 'How chords are rearranged so a different note is lowest, how to spot inversions on the staff, and why they make chord changes smooth.', cards: [
    { t: 'text', h: 'Same notes, different bass', p: ['A chord keeps its name whatever order its notes are in. What changes is the **lowest note**, and that gives the position:', '- **Root position**: the root is lowest. C E G.\n- **1st inversion**: the 3rd is lowest. E G C, written C/E.\n- **2nd inversion**: the 5th is lowest. G C E, written C/G.', 'To make the next inversion, move the bottom note up an octave.'] },
    { t: 'staff', h: 'C major, three ways', music: '"C" [C4,E4,G4]h "C/E" [E4,G4,C5]h | "C/G" [G4,C5,E5]h "C" [C5,E5,G5]h', p: ['Root position, 1st inversion, 2nd inversion, then root position an octave higher. Each has a slightly different colour, but it’s always C major.'] },
    { t: 'text', h: 'Spotting inversions on the staff', p: ['A root-position triad is the neat snowman, every note a 3rd apart. In an inversion, one gap is wider: a **4th**. The **top note of the 4th is the root**.', 'If the 4th is at the top, it’s 1st inversion (E G **C**). If the 4th is at the bottom, it’s 2nd inversion (G **C** E).'] },
    { t: 'quiz', q: 'Which chord is this, and in which position?', staff: '[A4,D5,F5]w', opts: ['Dm, 2nd inversion', 'Dm, 1st inversion', 'F, root position', 'Am, 1st inversion'], ans: 0, why: 'The wide gap is A–D, a 4th, so D is the root: D F A is D minor. Its 5th, A, is lowest, so it’s 2nd inversion.' },
    { t: 'text', h: 'Why inversions matter', p: ['Playing every chord in root position makes your hand jump around. With inversions you can choose the shape **nearest** the last chord, so shared notes stay put and the others move by a step or two.', 'This is called **voice leading**, and it’s how pianists play chords in real music. It sounds smoother, and it’s easier on the hand.'] },
    { t: 'staff', h: 'Jumping or gliding', music: '"C" [C4,E4,G4]q "F" [F4,A4,C5]q "G" [G4,B4,D5]q "C" [C4,E4,G4]q | "C" [C4,E4,G4]q "F/C" [C4,F4,A4]q "G/B" [B3,D4,G4]q "C" [C4,E4,G4]q', p: ['{Bar} 1 uses root position only, so the whole hand leaps. {Bar} 2 plays the same chords with inversions: C stays put for F/C, and no note moves further than a 3rd.'] },
    { t: 'quiz', q: 'Which notes make **G major in 1st inversion**?', opts: ['B D G', 'D G B', 'G B D'], ans: 0, why: '1st inversion puts the 3rd at the bottom. The 3rd of G major is B, so the chord is B D G, written G/B.' },
    { t: 'quiz', q: 'What does **F/A** tell you to play?', opts: ['An F chord with A as the lowest note', 'An F chord, then an A chord', 'An A chord with F as the lowest note'], ans: 0, why: 'The chord comes before the slash and the bass note after it. F/A is F major (F A C) in 1st inversion: A C F.' },
    { t: 'task', h: 'Try this now', steps: ['Write C, F and G major in root position, then write each one in 1st and 2nd inversion by moving the bottom note to the top.', 'In every inversion, find the 4th and circle its top note. Check that it’s the root.', 'Label each inversion with a slash chord symbol, such as F/A and F/C.', 'Plan a smooth path for C–Am–F–G that keeps shared notes and moves the others by step. One answer: C E G, C E A, C F A, B D G.'] },
    { t: 'drill', h: 'Name chords in any shape', spec: { k: 'chordname', chords: ['C', 'F', 'G', 'Am', 'Dm', 'Em'], inversions: true, count: 8 } },
  ] },
  { id: 'th-sevenths', u: 5, title: 'Seventh chords', mins: 7, sum: 'How dominant, major and minor 7th chords are built, how each one sounds, and why V7 pulls so strongly towards I.', cards: [
    { t: 'text', h: 'One more 3rd', p: ['Stack another 3rd on top of a triad and you reach the **7th** above the root. The result is a four-note **seventh chord**, richer than a triad.', 'Which triad you start with, and which size of 7th you add, gives three everyday seventh chords.'] },
    { t: 'text', h: 'The big three', p: ['- **Dominant 7th** (C7): major triad + minor 7th. C E G B♭. Bluesy and restless, it wants to move. [[chord:C7]]\n- **Major 7th** (Cmaj7): major triad + major 7th. C E G B. Soft and dreamy. [[chord:Cmaj7]]\n- **Minor 7th** (Cm7): minor triad + minor 7th. C E♭ G B♭. Mellow and smooth. [[chord:Cm7]]'] },
    { t: 'staff', h: 'Three sevenths on C', music: '"C7" [C4,E4,G4,Bb4]h "Cmaj7" [C4,E4,G4,B4]h | "Cm7" [C4,Eb4,G4,Bb4]h "C" [C4,E4,G4]h', p: ['Compare each one with the plain C triad at the end. The top note makes all the difference: B♭ sounds bluesy, B sounds dreamy.'] },
    { t: 'text', h: 'Why it’s called dominant', p: ['The chord on the 5th note of a major key is the **dominant**, V. Add a 7th from the key’s own notes and you get the **dominant 7th**, V7. In C major that’s **G7**: G B D F, all white keys.', 'G7 holds two restless notes. **B**, the leading note, wants to rise to C, and **F** wants to fall to E. Together they pull straight into the C chord.'] },
    { t: 'staff', h: 'V7 resolves to I', music: '"G7" [B3,D4,F4,G4]h "C" [C4,E4,G4]h | "C7" [C4,E4,G4,Bb4]h "F" [C4,F4,A4]h', p: ['G7 to C in C major: B rises to C and F falls to E. Then C7 to F in F major: E rises to F and B♭ falls to A. Each dominant 7th lands on the chord a 5th below.'] },
    { t: 'quiz', q: 'Which chord is the dominant 7th in C major?', opts: ['G7', 'C7', 'Cmaj7'], ans: 0, why: 'The dominant is chord V, built on the 5th note. In C major that’s G, so the dominant 7th is G7 (G B D F).' },
    { t: 'quiz', q: 'Cmaj7 and C7 differ by one note. Which?', opts: ['B in Cmaj7, B♭ in C7', 'E in Cmaj7, E♭ in C7', 'G in Cmaj7, G♯ in C7'], ans: 0, why: 'Both start with C major (C E G). Cmaj7 adds the major 7th, B; C7 adds the minor 7th, B♭.' },
    { t: 'quiz', q: 'Which notes make **Am7**?', opts: ['A C E G', 'A C♯ E G', 'A C E G♯'], ans: 0, why: 'A minor (A C E) plus a minor 7th, G. A minor triad with a minor 7th is a minor 7th chord, and Am7 uses only white keys.' },
    { t: 'task', h: 'Try this now', steps: ['Spell G7, C7 and F7: a major triad plus the note a {tone} below the root.', 'Spell Cmaj7, Fmaj7 and Gmaj7: a major triad plus the note a {semi} below the root.', 'Spell Am7, Dm7 and Em7, which use only white keys.', 'Check: G B D F, C E G B♭, F A C E♭; C E G B, F A C E, G B D F♯; A C E G, D F A C, E G B D.', 'Put on some jazz or soul and listen for soft, rich chords: many of them are maj7 and m7 chords.'] },
    { t: 'drill', h: 'Hear the difference (headphones on)', spec: { k: 'ear', mode: 'quality', set: ['', 'm', '7', 'maj7'], count: 8 } },
  ] },

  /* ===================== Unit 6: Progressions ===================== */
  { id: 'th-diatonic', u: 6, title: 'Chords in a key', mins: 7, sum: 'How to build a triad on every note of a major scale, and the major–minor–diminished pattern that every major key shares.', cards: [
    { t: 'text', h: 'A chord on every step', p: ['Take the C major scale and build a triad on each note, using only notes from the scale (all white keys). You get seven chords, one for each **scale degree**. These are the **chords of the key**, also called diatonic chords.', 'Most songs in C major use mainly these seven chords, so knowing them tells you which chords to expect.'] },
    { t: 'staff', h: 'The seven chords of C major', music: '"C" [C4,E4,G4]q "Dm" [D4,F4,A4]q "Em" [E4,G4,B4]q "F" [F4,A4,C5]q | "G" [G4,B4,D5]q "Am" [A4,C5,E5]q "Bdim" [B4,D5,F5]q "C" [C5,E5,G5]q', p: ['Every chord is a snowman of white keys. Tap through them: some sound bright (major), some darker (minor), and one, B diminished, sounds tense.'] },
    { t: 'text', h: 'The pattern', p: ['Number the chords by scale degree, 1 to 7. The same pattern of chord types appears in every major key:', '- **1, 4 and 5** are major.\n- **2, 3 and 6** are minor.\n- **7** is diminished.', 'In Roman numerals that’s **I ii iii IV V vi vii°**: capitals for major, small letters for minor, and ° for diminished.'] },
    { t: 'staff', h: 'The seven chords of G major', key: 'G', music: '"G" [G4,B4,D5]q "Am" [A4,C5,E5]q "Bm" [B4,D5,F#5]q "C" [C5,E5,G5]q | "D" [D4,F#4,A4]q "Em" [E4,G4,B4]q "F#dim" [F#4,A4,C5]q "G" [G4,B4,D5]q', p: ['The key signature turns every F into F♯, and the same pattern appears: G, Am, Bm, C, D, Em, F♯dim.'] },
    { t: 'text', h: 'Three keys side by side', p: ['- **C major**: C, Dm, Em, F, G, Am, Bdim\n- **G major**: G, Am, Bm, C, D, Em, F♯dim\n- **F major**: F, Gm, Am, B♭, C, Dm, Edim', 'Neighbouring keys share chords. C and G major both have C, Em, G and Am. C and F major both have C, Dm, F and Am. That’s why music can slip so easily between them.'] },
    { t: 'quiz', q: 'In G major, which chord is **iii**?', opts: ['Bm', 'B', 'Em'], ans: 0, why: 'The 3rd note of G major is B. Chord iii is always minor, so it’s B minor: B D F♯.' },
    { t: 'quiz', q: 'Which chord does **not** belong to F major?', opts: ['B', 'B♭', 'Gm', 'Dm'], ans: 0, why: 'F major has B♭ in its key signature, so its chord on the 4th degree is B♭ (B♭ D F). A B major chord needs B, D♯ and F♯, none of which are in the key.' },
    { t: 'quiz', q: 'Why is the chord on the 7th degree diminished?', opts: ['Both of its 3rds are minor', 'Both of its 3rds are major', 'It has no 5th'], ans: 0, why: 'In C, B to D and D to F are both minor 3rds (3 {semis} each). Two minor 3rds make a diminished triad, with a tense 5th of only 6 {semis}.' },
    { t: 'task', h: 'Try this now', steps: ['Write the D major scale on paper: D E F♯ G A B C♯ D.', 'Build a triad on each note by skipping letters, using only notes from that scale.', 'Label each chord with its name and Roman numeral, following the pattern I ii iii IV V vi vii°.', 'Check: D, Em, F♯m, G, A, Bm, C♯dim.', 'Circle the three major chords, I, IV and V. They’re the backbone of most songs in D.'] },
    { t: 'drill', h: 'Chords and numerals', spec: { k: 'roman', keys: ['C', 'G', 'F'], count: 8 } },
  ] },
  { id: 'th-romans', u: 6, title: 'Roman numerals', mins: 6, sum: 'How Roman numerals name chords by their place in the key, so you can write a progression once and play it in any key.', cards: [
    { t: 'text', h: 'Chords by number', p: ['Musicians often name chords by their **scale degree** rather than their letters, using Roman numerals. **I** is the chord on the 1st note of the key, **IV** the chord on the 4th, and **V** the chord on the 5th.', 'The big advantage: a numeral describes the chord’s *job* in the key rather than its letters, so the same numerals work in every key.'] },
    { t: 'text', h: 'Reading the symbols', p: ['- **Capitals** (I, IV, V) mean major.\n- **Small letters** (ii, iii, vi) mean minor.\n- **°** means diminished (vii°).\n- A small **7** adds the 7th: **V7** is the dominant 7th, and **ii7** is a minor 7th chord on the 2nd degree.', 'In a minor key the home chord is minor, so it’s written **i**.'] },
    { t: 'staff', h: 'I–IV–V–I in two keys', rh: '"C" [C4,E4,G4]q "F" [C4,F4,A4]q "G" [B3,D4,G4]q "C" [C4,E4,G4]q | "G" [B3,D4,G4]q "C" [C4,E4,G4]q "D" [A3,D4,F#4]q "G" [B3,D4,G4]q', lh: 'C3q F2q G2q C3q | G2q C3q D3q G2q', p: ['{Bar} 1 is I–IV–V–I in C major: C, F, G, C. {Bar} 2 uses the same numerals in G major: G, C, D, G. Different letters, the same journey.'] },
    { t: 'quiz', q: 'In G major, what are chords I, IV and V?', opts: ['G, C and D', 'G, C and E', 'C, F and G'], ans: 0, why: 'Count up the G major scale: G (1), A, B, C (4), D (5). All three chords are major: G, C and D.' },
    { t: 'text', h: 'Turning numerals into chords', p: ['To play numerals in any key, write out the scale and number its notes 1 to 7. Build each chord on the matching note, and let the numeral’s capitals or small letters tell you major or minor.', 'Example: **I–vi–IV–V** in F major. The scale is F G A B♭ C D E, so I = **F**, vi = **Dm**, IV = **B♭** and V = **C**.'] },
    { t: 'quiz', q: 'In D major, which chord is **vi**?', opts: ['Bm', 'B', 'Am'], ans: 0, why: 'The 6th note of D major (D E F♯ G A B C♯) is B, and vi is minor: B D F♯, B minor.' },
    { t: 'quiz', q: 'In C major, Dm7 is which numeral?', opts: ['ii7', 'II7', 'iv7'], ans: 0, why: 'D is the 2nd note of C major. The chord is minor, so the numeral is in small letters, and the 7 shows the added 7th: ii7.' },
    { t: 'task', h: 'Try this now', steps: ['Write I–V–vi–IV in C, G, F and D major.', 'Check: C–G–Am–F; G–D–Em–C; F–C–Dm–B♭; D–A–Bm–G.', 'Now go the other way. In G major, give numerals to the chords Am, D7 and Em. Answer: ii, V7 and vi.', 'Pick a song with simple chords, find its key, and rewrite its chords as numerals.'] },
    { t: 'drill', h: 'Numerals in four keys', spec: { k: 'roman', keys: ['C', 'G', 'F', 'D'], count: 8 } },
  ] },
  { id: 'th-function', u: 6, title: 'Home, away and tension', mins: 7, sum: 'Why chords I, IV and V feel like home, a step away and tension, and how those three chords can harmonise a simple tune.', cards: [
    { t: 'text', h: 'Every chord has a job', p: ['In a key, chords behave like places on a journey. The three most important are:', '- **Tonic** (I): home. Restful and finished.\n- **Subdominant** (IV): moving away. Open and hopeful.\n- **Dominant** (V): tension. It leans strongly back towards home.', 'A huge amount of music simply goes home, away, tension, home: I–IV–V–I.'] },
    { t: 'text', h: 'The leading note', p: ['Why does V want to go home so badly? The 7th note of the major scale sits just a {semi} below the tonic, so it pulls upwards. It’s called the **leading note**: B in C major ([[B4]] then [[C5]]).', 'The V chord contains the leading note (G B D), and V7 adds F, which pulls down to E. When V moves to I, those notes settle and the music arrives home.'] },
    { t: 'staff', h: 'Home, away, tension, home', rh: '"C" [C4,E4,G4]h "F" [C4,F4,A4]h | "G7" [B3,D4,F4,G4]h "C" [C4,E4,G4]h', lh: 'C3h F2h | G2h C3h', p: ['I–IV–V7–I in C major. Listen for the pull in G7 and the relief when it reaches C.'] },
    { t: 'text', h: 'The three primary chords', p: ['I, IV and V are the **primary chords**. Between them they contain every note of the scale: C E G, F A C and G B D cover C, D, E, F, G, A and B.', 'So you can harmonise many simple melodies with just these three. For each beat or {bar}, choose the chord that contains the main melody notes. When two chords fit, let your ear decide.'] },
    { t: 'staff', h: '“Twinkle Twinkle” with I, IV and V', rh: '"C" C4q C4q G4q G4q | "F" A4q A4q "C" G4h | "F" F4q F4q "C" E4q E4q | "G" D4q D4q "C" C4h', lh: 'C3w | F3h C3h | F3h C3h | G3h C3h', p: ['Each chord contains the melody note above it: A is in F, G is in C, D is in G. Only three chords, yet it sounds complete.'] },
    { t: 'quiz', q: 'Which chord in C major contains the leading note?', opts: ['G', 'F', 'C'], ans: 0, why: 'The leading note in C major is B. G major (G B D) contains it, which is one reason V pulls so strongly back to I.' },
    { t: 'quiz', q: 'In C major, a melody note A lasts a whole {bar}. Which primary chord fits it?', opts: ['F', 'G', 'C'], ans: 0, why: 'F major is F A C, so it contains A. C (C E G) and G (G B D) don’t.' },
    { t: 'quiz', q: 'In G major, which chord is the **subdominant**?', opts: ['C', 'D', 'Em'], ans: 0, why: 'The subdominant is IV, built on the 4th note. In G major (G A B C D E F♯) that’s C.' },
    { t: 'task', h: 'Try this now', steps: ['Write the letters of “Mary Had a Little Lamb” in C major, one {bar} per group: E D C D | E E E | D D D | E G G | E D C D | E E E E | D D E D | C.', 'For each {bar}, choose C, F or G: the chord that contains most of the melody notes.', 'Check: C, C, G, C, C, C, G, C. This tune needs only I and V.', 'Hum the tune and imagine the chords underneath. Feel the tension at each G and the relief when C returns.', 'Next time you’re at the piano, play the melody in your right hand and the chord roots in your left.'] },
  ] },
  { id: 'th-cadences', u: 6, title: 'Cadences: how phrases end', mins: 7, sum: 'The four main cadences, the chord pairs that end musical phrases, and how to spot them by ear and on paper.', cards: [
    { t: 'text', h: 'Musical punctuation', p: ['A **cadence** is the pair of chords at the end of a phrase. Like punctuation, it tells you how the phrase ends: with a full stop, a comma, or a surprise.', 'There are four main cadences, and each is defined by its last two chords.'] },
    { t: 'staff', h: 'Two cadences that finish', rh: '"G" [B3,D4,G4]h "C" [C4,E4,G4]h | "F" [C4,F4,A4]h "C" [C4,E4,G4]h', lh: 'G2h C3h | F2h C3h', p: ['{Bar} 1 is a **perfect** (authentic) cadence, V–I: strong and final, a full stop. {Bar} 2 is a **plagal** cadence, IV–I: softer, the “Amen” at the end of a hymn.'] },
    { t: 'staff', h: 'Two cadences that don’t', rh: '"C" [C4,E4,G4]h "G" [B3,D4,G4]h | "G" [B3,D4,G4]h "Am" [C4,E4,A4]h', lh: 'C3h G2h | G2h A2h', p: ['{Bar} 1 is an **imperfect** (half) cadence, ending on V: it sounds like a comma, waiting for more. {Bar} 2 is an **interrupted** (deceptive) cadence, V–vi: you expect home, and get A minor instead.'] },
    { t: 'text', h: 'The four cadences', p: ['- **Perfect** (authentic): V–I. Final, like a full stop.\n- **Plagal**: IV–I. A gentle “Amen” ending.\n- **Imperfect** (half): ends on V, often I–V, IV–V or ii–V. Like a comma or a question.\n- **Interrupted** (deceptive): V–vi. A surprise that keeps the music going.'] },
    { t: 'text', h: 'Spotting cadences', p: ['Look at the last chord of each phrase. If it’s **V**, the cadence is imperfect. If it’s **I**, check the chord before it: V means perfect, IV means plagal. If you expected I but got **vi**, it’s interrupted.', 'By ear, perfect cadences sound finished, imperfect ones sound like a question, and interrupted ones sound like a sidestep. Many tunes end their first phrase with an imperfect cadence and the next with a perfect one.'] },
    { t: 'quiz', q: 'A phrase in C major ends with F then C. Which cadence is it?', opts: ['Plagal', 'Perfect', 'Interrupted', 'Imperfect'], ans: 0, why: 'F to C is IV–I in C major: the plagal, or “Amen”, cadence.' },
    { t: 'quiz', q: 'A phrase ends on chord V. Which cadence is it?', opts: ['Imperfect (half)', 'Perfect (authentic)', 'Plagal'], ans: 0, why: 'Any cadence that ends on V is imperfect. It sounds unfinished, like a question waiting for its answer.' },
    { t: 'quiz', q: 'A phrase in G major ends with D then Em. Which cadence is it?', opts: ['Interrupted (deceptive)', 'Perfect (authentic)', 'Imperfect (half)'], ans: 0, why: 'In G major, D is V and Em is vi. V–vi is the interrupted cadence: the ear expects G and gets E minor.' },
    { t: 'task', h: 'Try this now', steps: ['Write all four cadences in C major as chord names: perfect G–C, plagal F–C, imperfect C–G and interrupted G–Am.', 'Now write them in G major. Check: D–G, C–G, G–D and D–Em.', 'Then write them in F major. Check: C–F, B♭–F, F–C and C–Dm.', 'Listen to a hymn, carol or folk song and decide at each phrase end whether it sounds finished (perfect or plagal) or unfinished (imperfect).'] },
  ] },
  { id: 'th-progressions', u: 6, title: 'Famous progressions', mins: 8, sum: 'The chord patterns behind thousands of songs, from I–V–vi–IV to the 12-bar blues, and how to recognise and transpose them.', cards: [
    { t: 'text', h: 'The same few patterns', p: ['A **chord progression** is a series of chords. A handful of progressions turn up again and again, in every style from hymns to pop. Learn them in Roman numerals and you can play them in any key, and often recognise them in songs you hear.'] },
    { t: 'text', h: 'Four-chord favourites', p: ['- **I–V–vi–IV**: the great pop progression, used in “Let It Be” and countless other songs. In C: C–G–Am–F.\n- **I–vi–IV–V**: the ’50s doo-wop progression, heard in “Stand by Me”. In C: C–Am–F–G.\n- **vi–IV–I–V**: the pop progression starting on its minor chord. In C: Am–F–C–G.\n- **i–VI–III–VII**: the epic minor progression. In A minor: Am–F–C–G.', 'The last two use the same four chords. Whether they sound major or minor depends on which chord feels like home.'] },
    { t: 'staff', h: 'I–V–vi–IV in C', rh: '"C" [C4,E4,G4]w | "G" [B3,D4,G4]w | "Am" [C4,E4,A4]w | "F" [C4,F4,A4]w', lh: 'C3w | G2w | A2w | F2w', p: ['C–G–Am–F, with the right hand in inversions so it barely moves. The bass plays the roots: C, G, A, F. Once you know this sound, you’ll hear it all over pop music.'] },
    { t: 'text', h: 'The 12-bar blues', p: ['The blues uses just I, IV and V, usually as 7th chords, over twelve {bars}:', '- {Bars} 1–4: **I7 I7 I7 I7**\n- {Bars} 5–8: **IV7 IV7 I7 I7**\n- {Bars} 9–12: **V7 IV7 I7 V7**', 'In C that’s C7 for four {bars}, F7 for two, C7 for two, then G7, F7, C7 and G7, which leads back to the start. Much early rock and roll uses the same plan.'] },
    { t: 'text', h: 'Jazz and Baroque classics', p: ['**ii–V–I** is the heart of jazz. In C it’s often played with 7ths: **Dm7–G7–Cmaj7**. Each root falls a 5th to the next, so the progression flows strongly home.', '**Pachelbel’s Canon** cycles through **I–V–vi–iii–IV–I–IV–V**. In C: C–G–Am–Em–F–C–F–G. Many later songs borrow all or part of it.'] },
    { t: 'text', h: 'Recognising them', p: ['On paper, write the chords of a song as numerals and look for these patterns. By ear, follow the **bass line**: I–V–vi–IV has roots 1–5–6–4, while the doo-wop progression has 1–6–4–5.', 'In a blues, listen for the move to IV in {bar} 5 and the V chord in {bar} 9 that leads back home. In a minor key, the epic i–VI–III–VII sounds bold and heroic.'] },
    { t: 'quiz', q: 'In G major, the chords G–D–Em–C are which progression?', opts: ['I–V–vi–IV', 'I–vi–IV–V', 'I–IV–V–I'], ans: 0, why: 'In G major, G is I, D is V, Em is vi and C is IV. It’s the pop progression, I–V–vi–IV.' },
    { t: 'quiz', q: 'What is ii–V–I in F major, with 7ths?', opts: ['Gm7–C7–Fmaj7', 'G7–C7–F7', 'Dm7–G7–Cmaj7'], ans: 0, why: 'F major’s 2nd note is G (a minor chord), its 5th is C, and I is F. With 7ths that’s Gm7, C7 and Fmaj7.' },
    { t: 'quiz', q: 'In a 12-bar blues, which chord starts {bar} 5?', opts: ['IV7', 'V7', 'I7'], ans: 0, why: 'The first four {bars} stay on I7, then {bar} 5 moves to IV7 for two {bars} before returning to I7.' },
    { t: 'task', h: 'Try this now', steps: ['Write I–V–vi–IV and I–vi–IV–V in G major. Check: G–D–Em–C and G–Em–C–D.', 'Write a 12-bar blues in G with 7th chords, four {bars} to a line. Check: G7 G7 G7 G7 | C7 C7 G7 G7 | D7 C7 G7 D7.', 'Write ii–V–I in G major with 7ths. Check: Am7–D7–Gmaj7.', 'Listen to a few songs you like and see whether any of them use one of these progressions.'] },
  ] },
  { id: 'th-leadsheets', u: 6, title: 'Lead sheets and chord charts', mins: 7, sum: 'How to read a melody with chord symbols, choose a left-hand pattern, and make your own arrangement from a lead sheet or chord chart.', cards: [
    { t: 'text', h: 'Melody plus chords', p: ['A **lead sheet** gives you just the melody, on a treble staff, with chord symbols above it. The accompaniment is up to you. Pop, jazz and folk songs are often written down this way.', 'Each chord symbol lasts until the next one appears, even across several {bars}.'] },
    { t: 'staff', h: '“Ode to Joy” as a lead sheet', music: '"C" E4q E4q F4q G4q | "G" G4q F4q E4q D4q | "C" C4q C4q D4q E4q | "G" E4q. D4e D4h | "C" E4q E4q F4q G4q | "G" G4q F4q E4q D4q | "C" C4q C4q D4q E4q | "G" D4q. C4e "C" C4h', p: ['Just two chords, C and G, carry the whole tune. Here a new symbol appears in every {bar}, but in other songs one chord can last for several {bars}.'] },
    { t: 'text', h: 'Choosing a left hand', p: ['Start simple and add more as you grow confident:', '- **Roots**: the chord’s root as a {w}, or on every beat.\n- **Root and 5th**: both together, for an open, solid sound.\n- **Block chords**: the whole chord on beat 1, or on every beat.\n- **Broken chords**: root, 5th, 3rd, 5th as {es} or {qs}, for a flowing sound.', 'Meanwhile the right hand plays the melody.'] },
    { t: 'staff', h: 'Melody and roots', rh: '"C" E4q E4q F4q G4q | "G" G4q F4q E4q D4q | "C" C4q C4q D4q E4q | "G" E4q. D4e D4h', lh: 'C3w | G3w | C3w | G3w', p: ['The simplest arrangement: the melody in the right hand and each chord’s root as a {w} in the left. Once that’s easy, try another left-hand pattern.'] },
    { t: 'text', h: 'Chord charts', p: ['A **chord chart** leaves out the melody altogether: just {bars} and chord symbols. The symbol takes the first beat and each slash adds one more, so | C / / / | is four beats of C, and | F / G / | is two beats of F, then two of G.', 'Charts also use **slash chords** for bass lines, such as C–G/B–Am, where the bass walks down C, B, A. **N.C.** means no chord: the accompaniment stops.'] },
    { t: 'text', h: 'Repeats and endings', p: ['Lead sheets save space with **repeat signs**: a thick and thin bar line with two dots. Go back to the matching sign facing the other way, or to the start if there isn’t one, and play the section again.', 'With **first and second-time {bars}**, play the first-time {bar} on the way through. On the repeat, skip it and play the second-time {bar} instead.'] },
    { t: 'quiz', q: 'A lead sheet shows **Am** over {bar} 1 and no symbol over {bar} 2. What do you play in {bar} 2?', opts: ['Keep playing Am', 'No chord', 'Go back to C'], ans: 0, why: 'A chord symbol lasts until the next one appears, so Am carries on through {bar} 2.' },
    { t: 'quiz', q: 'In a chord chart, what does | F / G / | mean?', opts: ['Two beats of F, then two of G', 'One beat of F, then three of G', 'One {bar} of F, then one {bar} of G'], ans: 0, why: 'Each chord symbol takes a beat and each slash adds one more: F, slash, G, slash makes two beats each.' },
    { t: 'quiz', q: 'What does **D/F♯** ask the left hand to play?', opts: ['F♯ in the bass, under a D chord', 'D in the bass, under an F♯ chord', 'A D chord, then an F♯ chord'], ans: 0, why: 'The note after the slash is the bass. D/F♯ is a D major chord (D F♯ A) with F♯ as the lowest note.' },
    { t: 'task', h: 'Try this now', steps: ['Choose a simple song you know well, such as “Happy Birthday” or a carol, and find its chords in a songbook or online.', 'Write a chord chart for it: draw the {bars}, then add the chord symbols and a slash for each extra beat.', 'Mark any repeated sections with repeat signs, and any different endings with first and second-time {bars}.', 'Plan a left-hand pattern: roots to begin with, then block or broken chords when you’re ready.', 'Next time you’re at the piano, play from your chart, with the melody in the right hand and your planned pattern in the left.'] },
  ] },

  /* ===================== Unit 7: Reading fluently ===================== */
  { id: 'th-ledger', u: 7, title: 'Ledger lines and the wide range', mins: 6, sum: 'How to read notes far above and below the staff, using ledger lines, landmark Cs and the 8va sign.', cards: [
    { t: 'text', h: 'Beyond the five lines', p: ['When notes go higher or lower than the staff, they get short extra lines of their own, called **ledger lines**. Notes sit on them or in the spaces between them, just as they do on the staff.', 'You can read ledger notes by counting on from the staff in steps: line, space, line, space. It’s quicker, though, to learn a few **landmark** notes and count from the nearest one.'] },
    { t: 'staff', h: 'Above the treble staff', clef: 'treble', labels: true, music: 'F5q A5q C6q E6q | C6q A5q F5q rq', p: ['F is on the top line. A sits on the first ledger line above, **high C** (C6) on the second and E on the third. The ledger lines spell A, C, E going up, each a 3rd above the last.'] },
    { t: 'staff', h: 'Below the bass staff', clef: 'bass', labels: true, music: 'G2q E2q C2q A1q | C2q E2q G2q rq', p: ['G is on the bottom line. E sits on the first ledger line below, **low C** (C2) on the second and A on the third: E, C, A going down, a mirror image of the A, C, E above the treble staff.'] },
    { t: 'staff', h: 'Middle C on either staff', labels: true, rh: 'C4q D4q B3q A3q | rw', lh: 'rw | C4q D4q B3q A3q', p: ['**Middle C** sits on one ledger line: just below the treble staff or just above the bass staff. Here the same four notes, C, D, B and A, are written in the treble clef and then in the bass clef. Same sounds, different homes.'] },
    { t: 'text', h: '8va and 8vb', p: ['Lots of ledger lines are hard to read, so composers use a shortcut. **8va** (from the Italian *ottava*, octave) above some notes, with a dotted line after it, means play them an octave higher than written.', '**8vb** (or *8va bassa*) below the notes means play them an octave lower. When the dotted line ends, or you see *loco* (“in place”), go back to the written pitch.'] },
    { t: 'quiz', q: 'Which note is this?', staff: 'C6w', opts: ['High C (C6)', 'Middle C (C4)', 'A (A5)'], ans: 0, why: 'It sits on the second ledger line above the treble staff: high C, two octaves above Middle C.' },
    { t: 'quiz', q: 'In the bass clef, which note sits on the first ledger line **below** the staff?', opts: ['E', 'F', 'C'], ans: 0, why: 'The bottom line of the bass staff is G. Step down: F in the space just below, then E on the first ledger line.' },
    { t: 'quiz', q: 'What does **8va** above a group of notes mean?', opts: ['Play them an octave higher', 'Play them an octave lower', 'Play them eight times'], ans: 0, why: '8va is short for *ottava*, the octave. Above the notes it means play an octave higher than written, until the dotted line ends.' },
    { t: 'task', h: 'Try this now', steps: ['Draw a treble staff with three ledger lines above it. Name the notes on each line and in each space going up: G, A, B, C, D, E.', 'Draw a bass staff with three ledger lines below it and do the same going down: F, E, D, C, B, A.', 'Write Middle C on both staves: one ledger line below the treble staff, and one above the bass staff.', 'Picture the keyboard: Middle C near the centre, high C two octaves above it and low C two octaves below it.', 'Next time you’re at the piano, play each landmark C and say its name aloud.'] },
  ] },
  { id: 'th-circle', u: 7, title: 'The circle of fifths', mins: 8, sum: 'A map of all twelve major keys that shows their sharps and flats, their relative minors and which chords they share.', cards: [
    { t: 'text', h: 'Twelve keys on a clock', p: ['The **circle of fifths** arranges all twelve major keys like the numbers on a clock face. C major, with no sharps or flats, sits at the top.', 'Go **clockwise** and each key is a perfect 5th higher, with one more sharp: C, G, D, A, E, B, F♯. Go **anticlockwise** and each key is a 5th lower, with one more flat: C, F, B♭, E♭, A♭, D♭, G♭.', 'At the bottom, F♯ major (six sharps) and G♭ major (six flats) meet. They sound the same and use the same piano keys, just written differently.'] },
    { t: 'text', h: 'The order of sharps and flats', p: ['Sharps are always added in the same order, each a 5th above the last: **F♯ C♯ G♯ D♯ A♯ E♯ B♯**. Flats come in the reverse order: **B♭ E♭ A♭ D♭ G♭ C♭ F♭**. A memory aid: *Father Charles Goes Down And Ends Battle*, read backwards for the flats.', 'To name a sharp key, go up a {semi} from the last sharp: F♯ C♯ means D major. To name a flat key, read the second-last flat: B♭ E♭ A♭ means E♭ major. F major, with just B♭, is the one to remember.'] },
    { t: 'quiz', q: 'How many sharps does A major have?', opts: ['3', '2', '4'], ans: 0, why: 'Count clockwise from C: G (1), D (2), A (3). A major has F♯, C♯ and G♯.' },
    { t: 'text', h: 'Relative minors', p: ['Every major key shares its key signature with a **relative minor**. Its home note is the major key’s 6th note, a minor 3rd (3 {semis}) below the tonic. C major and A minor both have no sharps or flats.', 'On the circle, write each relative minor inside its major: Am, Em, Bm, F♯m, C♯m and G♯m on the sharp side, and Dm, Gm, Cm, Fm and B♭m on the flat side.'] },
    { t: 'quiz', q: 'What is the relative minor of D major?', opts: ['B minor', 'D minor', 'F♯ minor'], ans: 0, why: 'The relative minor starts on the 6th note of the major scale. In D major (D E F♯ G A B C♯) that’s B, so B minor shares its two sharps.' },
    { t: 'text', h: 'Neighbours share chords', p: ['A key’s **I, IV and V** chords are the key itself and its two neighbours on the circle. For C major they’re C, with F one step anticlockwise and G one step clockwise.', 'Neighbouring keys differ by only one note, so they share most of their chords. That’s why music moves so easily to the key next door, and why the circle is a handy map for finding chords.'] },
    { t: 'staff', h: 'I, IV and V in E♭ major', key: 'Eb', rh: '"Eb" [Eb4,G4,Bb4]h "Ab" [Eb4,Ab4,C5]h | "Bb" [D4,F4,Bb4]h "Eb" [Eb4,G4,Bb4]h', lh: 'Eb3h Ab2h | Bb2h Eb3h', p: ['E♭ sits between A♭ and B♭ on the circle, so its primary chords are E♭, A♭ and B♭. The three flats in the key signature, B♭, E♭ and A♭, look after every note.'] },
    { t: 'quiz', q: 'A key signature has three flats. Which major key is it?', opts: ['E♭ major', 'B♭ major', 'A♭ major'], ans: 0, why: 'Count anticlockwise from C: F (1 flat), B♭ (2), E♭ (3). Or use the trick: the second-last flat, E♭, names the key.' },
    { t: 'task', h: 'Try this now', steps: ['Draw a large circle and mark twelve points around it, like a clock face.', 'Write C at the top. Going clockwise, add G, D, A, E, B and F♯; going anticlockwise, add F, B♭, E♭, A♭, D♭ and G♭, which meets F♯ at the bottom.', 'Next to each key, write how many sharps or flats it has.', 'Inside the circle, write each relative minor: Am inside C, Em inside G, Dm inside F, and so on.', 'Use your circle to find I, IV and V in A major and B♭ major. Check: A, D, E and B♭, E♭, F.'] },
    { t: 'drill', h: 'Keys and signatures', spec: { k: 'keyfind', keys: ['C', 'G', 'D', 'A', 'E', 'F', 'Bb', 'Eb', 'Ab'], count: 8 } },
  ] },
  { id: 'th-compound', u: 7, title: 'Simple and compound time', mins: 7, sum: 'The difference between beats that split in two and beats that split in three, and how to count 6/8, 9/8 and 12/8.', cards: [
    { t: 'text', h: 'Twos or threes', p: ['Every time signature has a **beat**, and beats can be split into smaller notes. In **simple time** each beat divides into two: in 2/4, 3/4 and 4/4 the beat is a {q}, which splits into two {es}.', 'In **compound time** each beat divides into **three**. The beat is a {dq}, which splits into three {es}. The common compound times are 6/8, 9/8 and 12/8.'] },
    { t: 'staff', h: 'Six {es} in 3/4', clef: 'rhythm', time: '3/4', music: 'xe xe xe xe xe xe | xq xq xq', p: ['Six {es} grouped in three pairs: three beats, each split in two. Count “1 & 2 & 3 &”.'] },
    { t: 'staff', h: 'Six {es} in 6/8', clef: 'rhythm', time: '6/8', music: 'xe xe xe xe xe xe | xq. xq.', p: ['The same six {es} grouped in two threes: two {dq} beats, each split in three. Count “**ONE** two three **FOUR** five six”, leaning on 1 and 4, or “1 & a 2 & a”.'] },
    { t: 'text', h: 'The compound family', p: ['The top number counts {es}, but you feel the beat in groups of three:', '- **6/8**: six {es}, two {dq} beats in a {bar}.\n- **9/8**: nine {es}, three {dq} beats.\n- **12/8**: twelve {es}, four {dq} beats.', 'Compound time gives music a lilting, rocking or galloping feel. Think of a jig, a lullaby or a slow blues ballad.'] },
    { t: 'quiz', q: 'How many beats are there in a {bar} of 6/8?', opts: ['2', '6', '3'], ans: 0, why: 'The six {es} are grouped in two sets of three, so you feel two {dq} beats in each {bar}.' },
    { t: 'staff', h: '“Row, Row, Row Your Boat” in 6/8', time: '6/8', music: 'C4q. C4q. | C4q D4e E4q. | E4q D4e E4q F4e | G4h.', p: ['Count six in each {bar} and feel the two big beats: **Row**, **row**, **row** your **boat**. A {q} followed by an {e} makes the long–short, skipping rhythm that’s typical of 6/8.'] },
    { t: 'quiz', q: 'How many {dq} beats are there in a {bar} of 12/8?', opts: ['4', '12', '6'], ans: 0, why: 'Twelve {es} make four groups of three, so 12/8 has four {dq} beats in each {bar}.' },
    { t: 'quiz', q: '3/4 and 6/8 both hold six {es}. What’s the difference?', opts: ['3/4 has three beats in twos; 6/8 has two beats in threes', '6/8 is always faster than 3/4', 'There’s no difference'], ans: 0, why: 'In 3/4 the {es} are grouped in pairs, making three {q} beats. In 6/8 they’re grouped in threes, making two {dq} beats. Same total, different feel.' },
    { t: 'task', h: 'Try this now', steps: ['Tap your knee on every count of “1 2 3 4 5 6”, tapping harder on 1 and 4. That’s 6/8.', 'Now count the same six taps as “1 & 2 & 3 &”, tapping harder on 1, 2 and 3. That’s 3/4. Switch between them and feel the difference.', 'Sing or hum “Row, Row, Row Your Boat” and tap just the two big beats in each {bar}.', 'On paper, write a {bar} of 6/8 in three different ways, such as two {dq}, six {es}, or a {q} and an {e} twice. Check that each adds up to six {es}.', 'Listen to a jig or a lullaby and count along in 6/8.'] },
    { t: 'drill', h: 'Complete the {bar}', spec: { k: 'barmath', level: 3, time: '6/8', count: 8 } },
  ] },
  { id: 'th-syncopation', u: 7, title: 'Ties, syncopation and triplets', mins: 7, sum: 'How ties stretch notes across beats and {bar} lines, how syncopation shifts the accent off the beat, and what triplets are.', cards: [
    { t: 'text', h: 'Ties', p: ['A **tie** is a curved line joining two notes of the **same pitch**. Play the first note and hold it through the second without playing again: the lengths add together.', 'Ties let a note last across a {bar} line, or across the middle of a {bar}. Don’t confuse a tie with a **slur**, which joins **different** notes to be played smoothly.'] },
    { t: 'staff', h: 'Holding across the {bar} line', music: 'C4h. E4q~ | E4h D4h | C4h~ C4e D4e E4e F4e | G4w', p: ['The E at the end of {bar} 1 is tied into {bar} 2, so it lasts three beats: one plus two. In {bar} 3, C lasts two and a half beats before the run up to G.'] },
    { t: 'text', h: 'Syncopation', p: ['Normally the strong beats carry the weight: beat 1 most of all, then beat 3 in 4/4. **Syncopation** moves the emphasis to weak beats, or to the “&” between beats, so the music seems to push ahead.', 'A classic pattern is short–long–short: an {e}, a {q}, then an {e}. The {q} starts on the “&” and sounds accented. Syncopation drives ragtime, jazz, Latin music and pop.'] },
    { t: 'staff', h: 'Accents between the beats', clef: 'rhythm', music: 'xq xq xq xq | xe xq> xe xq xq | xe xq> xq> xq> xe | xh xh', p: ['{Bar} 1 is plain beats. In {bar} 2 the accent lands on “1 &”, between beats 1 and 2. {Bar} 3 moves every accent onto an “&”. Count “1 & 2 & 3 & 4 &” and clap along.'] },
    { t: 'text', h: 'Triplets', p: ['A **triplet** squeezes three notes into the time of two of the same kind. It’s marked with a small **3** above or below the group.', 'The most common is the {e} triplet: three {es} in one {q} beat instead of the usual two. Say “one-trip-let, two-trip-let”, three even syllables to each beat. Triplets give a rolling feel, and they’re the basis of swing in jazz and blues.', 'A {bar} of 4/4 with triplets on every beat feels a lot like 12/8.'] },
    { t: 'quiz', q: 'How many beats does the first C last?', staff: 'C4h~ C4q D4q | E4w', opts: ['3', '2', '4'], ans: 0, why: 'The tie joins a {h} (2 beats) to a {q} (1 beat), so you hold C for 3 beats without playing it again.' },
    { t: 'quiz', q: 'What is **syncopation**?', opts: ['Emphasis on weak beats or between beats', 'Playing every note very short', 'Speeding up gradually'], ans: 0, why: 'Syncopation shifts the weight away from the strong beats, onto weak beats or the “&” between them.' },
    { t: 'quiz', q: 'An {e} triplet fills the same time as…', opts: ['One {q}', 'Three {qs}', 'One {h}'], ans: 0, why: 'Three triplet {es} fit into the time of two ordinary {es}, which is one {q} beat.' },
    { t: 'task', h: 'Try this now', steps: ['Clap a steady beat and say “1 & 2 & 3 & 4 &”. Then keep counting, but clap only on the “&”s.', 'Clap the short–long–short pattern (an {e}, a {q}, an {e}) over and over while tapping the beat with your foot.', 'Say “one-trip-let, two-trip-let” while tapping a steady beat, so that three even syllables fit each tap.', 'On paper, write a {bar} of 4/4 with a tie across the middle, and check that it still adds up to four beats.', 'Put on some funk, reggae or ragtime and listen for accents that land between the beats.'] },
    { t: 'drill', h: 'Hear the rhythm (headphones on)', spec: { k: 'rhythmhear', level: 4, time: '4/4', count: 6 } },
  ] },
  { id: 'th-form', u: 7, title: 'Form and musical road signs', mins: 8, sum: 'How pieces are built from phrases and sections, and how repeats, endings, D.C., D.S., Fine and Coda guide your route through the music.', cards: [
    { t: 'text', h: 'Phrases and sections', p: ['Music is built from **phrases**, musical sentences that are often four {bars} long. Phrases group into **sections**, and sections that sound alike get the same letter: A, B, and so on.', 'Knowing the form of a piece tells you which parts repeat, so there’s less to learn, and it helps you keep your place.'] },
    { t: 'text', h: 'Common forms', p: ['- **Binary (AB)**: two contrasting sections, often each repeated. Many Baroque dances are binary, such as Petzold’s Minuet in G.\n- **Ternary (ABA)**: a section, a contrast, then the first section again.\n- **Rondo (ABACA)**: a main theme that keeps returning between different episodes.\n- **Verse–chorus**: verses with new words each time, a chorus that repeats, and often a contrasting **bridge** near the end.'] },
    { t: 'quiz', q: '“Twinkle Twinkle Little Star” has a first part, a different middle part, then the first part again. What form is that?', opts: ['Ternary (ABA)', 'Binary (AB)', 'Rondo (ABACA)'], ans: 0, why: 'A, then a contrasting B, then A again: that’s ternary form, ABA.' },
    { t: 'text', h: 'Repeats and endings', p: ['A **repeat sign** (a double bar line with two dots) sends you back to the matching sign facing the other way, or to the beginning if there isn’t one. Play the section again, then carry on.', '**First and second-time {bars}** are brackets marked 1 and 2 over the end of a repeated section. Play the first-time {bar} the first time through. On the repeat, skip it and go straight to the second-time {bar}.'] },
    { t: 'text', h: 'Road signs: D.C. and D.S.', p: ['Some signs send you to a different place in the music:', '- **D.C.** (*da capo*, from the top): go back to the beginning.\n- **D.S.** (*dal segno*, from the sign): go back to **the sign**, a slanted S with a line through it and two dots.\n- **al Fine**: then play until the word **Fine** (Italian for “end”, said “fee-nay”).\n- **al Coda**: then play until **To Coda**, and jump to the **coda**, the closing section, marked with a circle and a cross.', 'So **D.C. al Fine** means go back to the start and stop at Fine.'] },
    { t: 'quiz', q: 'You reach **D.C. al Fine**. What do you do?', opts: ['Go back to the start and stop at Fine', 'Go back to the sign and stop at Fine', 'Jump straight to the coda'], ans: 0, why: 'D.C. (da capo) means from the top, the very beginning. Al Fine means play until you reach Fine, then stop.' },
    { t: 'quiz', q: 'A repeated section has first and second-time {bars}. What happens on the repeat?', opts: ['Skip the first-time {bar} and play the second', 'Play both endings', 'Play the first-time {bar} again'], ans: 0, why: 'The first-time {bar} is only for the first time through. On the repeat you go straight to the second-time {bar}.' },
    { t: 'tip', h: 'Map it before you play', p: ['Before playing a new piece, trace its route with your finger. Find the repeats, the endings, any D.C. or D.S., and where Fine or the coda is. Label the sections A, B and so on, and nothing will surprise you halfway through.'] },
    { t: 'task', h: 'Try this now', steps: ['Draw eight boxes for an eight-{bar} piece. Mark a repeat sign at the end of {bar} 4, with {bar} 4 as a first-time {bar} and {bar} 5 as the second-time {bar}.', 'Write down the order you’d play the {bars} in. Check: 1 2 3 4 1 2 3 5 6 7 8.', 'Now imagine a piece with Fine at the end of {bar} 4 and D.C. al Fine at the end of {bar} 8. Write its playing order. Check: {bars} 1 to 8, then 1 to 4.', 'Think of a favourite song and map its form, for example verse, chorus, verse, chorus, bridge, chorus.'] },
    { t: 'drill', h: 'Signs and symbols', spec: { k: 'terms', level: 7, cat: 'signs', count: 6 } },
  ] },

  /* ===================== Unit 8: Musicianship ===================== */
  { id: 'th-pentatonic', u: 8, title: 'Pentatonic and blues scales', mins: 7, sum: 'The five-note scales behind folk tunes, blues and rock, and why they make improvising so easy.', cards: [
    { t: 'text', h: 'Five notes, no clashes', p: ['A **pentatonic** scale has just five notes (*penta* is Greek for five). The **major pentatonic** takes degrees 1, 2, 3, 5 and 6 of the major scale and leaves out the 4th and 7th. In C that’s **C D E G A**.', 'Without the 4th and 7th there are no {semis} between neighbouring notes, so nothing clashes. That’s why the pentatonic sounds so open and friendly, and why folk music all over the world uses it.'] },
    { t: 'kb', h: 'C major pentatonic', from: 'C4', to: 'B5', labels: 'c', marks: [['C4', 'C', 'target'], ['D4', 'D', 'target'], ['E4', 'E', 'target'], ['G4', 'G', 'target'], ['A4', 'A', 'target'], ['C5', 'C', 'target'], ['D5', 'D', 'target'], ['E5', 'E', 'target'], ['G5', 'G', 'target'], ['A5', 'A', 'target']], p: ['Two octaves of C major pentatonic. Notice the gaps where F and B would be: the scale steps over them.'] },
    { t: 'text', h: 'The minor pentatonic', p: ['The **minor pentatonic** takes the natural minor scale and leaves out its 2nd and 6th notes, giving degrees 1, ♭3, 4, 5 and ♭7. In A that’s **A C D E G**: exactly the same notes as C major pentatonic, starting from A.', 'So every major pentatonic has a relative minor pentatonic, just like major and minor keys. The minor version sounds darker and bluesier, and it’s the backbone of countless rock and blues solos.'] },
    { t: 'staff', h: 'The blues scale', music: 'C4q Eb4q F4q F#4q | G4q Bb4q C5h', p: ['Add one note to the minor pentatonic, the ♭5, and you get the **blues scale**. In C: C, E♭, F, F♯, G, B♭, C. The F♯ is the “blue note”, a gritty passing note between F and G. In A, the blues scale is A, C, D, E♭, E, G.'] },
    { t: 'text', h: 'The black keys', p: ['Play only the black keys and you have a ready-made pentatonic scale: **G♭ A♭ B♭ D♭ E♭**, the G♭ major pentatonic. Start on E♭ instead and the same keys make E♭ minor pentatonic.', 'Because no two of them clash, any black keys sound good together. That makes them a perfect playground for improvising.'] },
    { t: 'tip', h: 'Improvising made easy', p: ['Next time you’re at the piano, hold a low C in your left hand and wander around C major pentatonic with your right. Or play a 12-bar blues in C with your left hand and try the C blues scale on top. With these scales, it’s hard to play a wrong note.'] },
    { t: 'quiz', q: 'Which notes make **G major pentatonic**?', opts: ['G A B D E', 'G A B C D', 'G B♭ C D F'], ans: 0, why: 'Take degrees 1, 2, 3, 5 and 6 of G major (G A B C D E F♯): G, A, B, D and E. The 4th (C) and 7th (F♯) are left out.' },
    { t: 'quiz', q: 'A minor pentatonic uses the same notes as…', opts: ['C major pentatonic', 'A major pentatonic', 'G major pentatonic'], ans: 0, why: 'A C D E G and C D E G A are the same five notes. A minor is the relative minor of C major, so their pentatonics match.' },
    { t: 'quiz', q: 'What does the blues scale add to the minor pentatonic?', opts: ['The ♭5, a “blue note”', 'The major 3rd', 'The major 7th'], ans: 0, why: 'The blues scale is the minor pentatonic plus the ♭5. In C, that adds F♯ (also called G♭) between F and G.' },
    { t: 'task', h: 'Try this now', steps: ['Write the major pentatonic scales of C, G and F by taking degrees 1, 2, 3, 5 and 6 of each major scale.', 'Check: C D E G A; G A B D E; F G A C D.', 'Write A minor pentatonic and E minor pentatonic, then add the ♭5 to each to make its blues scale.', 'Check: A C D E♭ E G and E G A B♭ B D.', 'Hum “Amazing Grace”: its melody uses only the five notes of a major pentatonic scale.'] },
  ] },
  { id: 'th-minorkeys', u: 8, title: 'Minor keys in depth', mins: 8, sum: 'The three forms of the minor scale, why minor keys borrow a leading note, and the chords and progressions that minor keys use.', cards: [
    { t: 'text', h: 'The natural minor', p: ['The **natural minor** scale uses the notes of its relative major, starting on the 6th note. A natural minor is A B C D E F G A, all white keys.', 'Its pattern is {tone}, {semi}, {tone}, {tone}, {semi}, {tone}, {tone}. Compared with A major, its 3rd, 6th and 7th notes are each a {semi} lower, and that gives minor its darker colour.'] },
    { t: 'text', h: 'Harmonic and melodic minor', p: ['In the natural minor, the 7th note (G in A minor) sits a {tone} below the tonic, so it doesn’t pull home strongly. The **harmonic minor** raises it a {semi} to make a leading note: A B C D E F **G♯** A. That leaves a wide, exotic-sounding gap of 3 {semis} between F and G♯.', 'The **melodic minor** smooths out that gap. Going up, it raises both the 6th and the 7th (F♯ and G♯); coming down, it returns to the natural minor.'] },
    { t: 'staff', h: 'Three kinds of A minor', key: 'Am', music: 'A4e B4e C5e D5e E5e F5e G5e A5e | A4e B4e C5e D5e E5e F5e G#5e A5e | A4e B4e C5e D5e E5e F#5e G#5e A5e | A5e G5e F5e E5e D5e C5e B4e A4e', p: ['Natural minor, then harmonic minor (with G♯), then melodic minor going up (with F♯ and G♯), and finally melodic minor coming down, which is the same as the natural minor.'] },
    { t: 'quiz', q: 'In E harmonic minor, which note is raised?', opts: ['D becomes D♯', 'C becomes C♯', 'G becomes G♯'], ans: 0, why: 'E natural minor is E F♯ G A B C D E. The harmonic minor raises the 7th, D, to D♯, a {semi} below E.' },
    { t: 'text', h: 'Chords and progressions in minor', p: ['Built on the natural minor, the chords of A minor are **i ii° III iv v VI VII**: Am, B°, C, Dm, Em, F and G. The harmonic minor’s G♯ turns v into a major **V**, E (E G♯ B), which pulls home to Am just as G pulls to C in C major.', '- **i–iv–V–i**: [[chord:Am|Am]]–[[chord:Dm|Dm]]–[[chord:E|E]]–[[chord:Am|Am]], the classic minor progression.\n- **i–VI–III–VII**: Am–F–C–G, the epic minor sound.\n- **i–VII–VI–V**: Am–G–F–E, with a bass line falling step by step.'] },
    { t: 'text', h: 'Relative or parallel?', p: ['A **relative** minor shares its key signature with a major key: A minor is the relative minor of C major. A **parallel** minor shares the same tonic: C minor is the parallel minor of C major, with three flats.', 'Songs in a major key sometimes borrow a chord from the parallel minor, such as Fm in C major, for a brief moment of shadow.'] },
    { t: 'quiz', q: 'What is the **parallel** minor of G major?', opts: ['G minor', 'E minor', 'D minor'], ans: 0, why: 'A parallel minor has the same tonic, so it’s G minor. E minor is G major’s relative minor, sharing its one sharp.' },
    { t: 'quiz', q: 'Why do minor keys usually use a **major** V chord?', opts: ['Its 3rd is a leading note that pulls to the tonic', 'It’s easier to play', 'The natural minor has no 5th note'], ans: 0, why: 'In A minor, E major contains G♯, the raised 7th of the scale, just a {semi} below A. That leading note pulls strongly home.' },
    { t: 'task', h: 'Try this now', steps: ['Write D minor in all three forms: natural, harmonic, and melodic going up.', 'Check: D E F G A B♭ C D; D E F G A B♭ C♯ D; D E F G A B C♯ D.', 'Write i–iv–V–i in D minor and E minor. Check: Dm–Gm–A–Dm and Em–Am–B–Em.', 'Name the relative and parallel minors of F major and D major. Check: Dm and Fm; Bm and Dm.', 'Listen to a piece in a minor key and notice where it feels most tense and where it feels most at home.'] },
    { t: 'drill', h: 'Minor scales on paper', spec: { k: 'scalespell', keys: ['Am', 'Em', 'Dm', 'Bm'], count: 6 } },
  ] },
  { id: 'th-melody', u: 8, title: 'How melodies work', mins: 7, sum: 'The building blocks of a good tune: steps and leaps, contour, motifs and sequences, and question and answer phrases.', cards: [
    { t: 'text', h: 'Steps and leaps', p: ['Most memorable melodies move mainly by **step**, to the next note up or down, with occasional **leaps** for interest. Steps sound smooth and singable; leaps add energy and surprise.', 'A big leap is usually followed by a step back the other way, which balances the jump. “Somewhere over the Rainbow” opens with a leap of an octave, then turns back down.'] },
    { t: 'text', h: 'Contour', p: ['The **contour** is the overall shape of a melody: draw a line through the notes and you can see it rise and fall. Many phrases form an **arch**, climbing to a high point and settling back down.', 'The highest note, the **climax**, often comes just once, usually past the middle of a phrase or piece. Saving it makes it special.'] },
    { t: 'text', h: 'Motif, repetition and sequence', p: ['A **motif** is a short, memorable idea of just a few notes. The four-note opening of Beethoven’s Fifth Symphony is the most famous example.', 'Composers make a little go a long way. **Repetition** plays a motif again unchanged. A **sequence** repeats it starting on a higher or lower note, so the same shape climbs or falls.'] },
    { t: 'staff', h: 'A sequence', music: 'C4q D4q E4q C4q | D4q E4q F4q D4q | E4q F4q G4q E4q | D4h C4h', p: ['One motif, C D E C, repeated a step higher twice: D E F D, then E F G E. That’s a sequence, climbing step by step, before the last {bar} settles home.'] },
    { t: 'text', h: 'Question and answer', p: ['Phrases often come in pairs. The **question** phrase ends away from home, often on the 2nd, 5th or 7th note of the scale, so it sounds unfinished. The **answer** often starts the same way but ends on the tonic, and the music feels complete.', 'You’ll recognise the chords at those endings: the question often ends with an imperfect cadence and the answer with a perfect one.'] },
    { t: 'staff', h: 'Question and answer in C', music: 'C4q E4q G4q E4q | F4q A4q G4h | E4q C4q D4q E4q | D4w | C4q E4q G4q E4q | F4q A4q G4h | E4q C4q D4q B3q | C4w', p: ['The first four {bars} end on D, the 2nd note: a question. The answer begins the same way, then changes its ending to land on C, home.'] },
    { t: 'quiz', q: 'A motif is repeated, starting each time on a higher note. What is this called?', opts: ['A sequence', 'A cadence', 'An inversion'], ans: 0, why: 'A sequence repeats a musical shape at a different pitch, higher or lower. Repeating it at the same pitch is simple repetition.' },
    { t: 'quiz', q: 'An answer phrase usually ends on…', opts: ['The tonic, the home note', 'The 7th note of the scale', 'The 2nd note of the scale'], ans: 0, why: 'The answer resolves the question by coming home to the tonic. Question phrases tend to end on other notes, such as the 2nd, 5th or 7th.' },
    { t: 'quiz', q: 'After a big leap up, what does a melody usually do next?', opts: ['Turn back down, often by step', 'Leap up again, even further', 'Stop completely'], ans: 0, why: 'A step back the other way balances the leap. It’s one reason melodies with big leaps still feel natural to sing.' },
    { t: 'task', h: 'Try this now', steps: ['Pick a tune you know well and draw its contour on paper as a line that rises and falls with the notes.', 'Mark where it moves by step and where it leaps, and circle its highest note.', 'Find a motif that comes back, and decide whether it returns at the same pitch (repetition) or higher or lower (a sequence).', 'Write your own 8-{bar} melody in C: a 4-{bar} question ending on D or G, then a 4-{bar} answer ending on C.', 'Next time you’re at the piano, play your melody and adjust any notes that don’t sound right.'] },
  ] },
  { id: 'th-earsongs', u: 8, title: 'Hearing intervals with songs', mins: 7, sum: 'How to recognise and sing intervals using songs you already know, and how to train your ear without a piano.', cards: [
    { t: 'text', h: 'Relative pitch', p: ['**Relative pitch** is the skill of hearing the distance between notes. Very few people can name a note out of thin air, but almost anyone can learn to recognise intervals.', 'It helps you play by ear, sing in tune, catch mistakes and learn new music faster. And you can practise it anywhere, with no piano in sight.'] },
    { t: 'text', h: 'A song for every interval', p: ['Link each rising interval to a tune you already know. Each one uses the first two notes, unless noted:', '- **Minor 2nd**: the *Jaws* theme\n- **Major 2nd**: “Frère Jacques”\n- **Minor 3rd**: “Greensleeves”\n- **Major 3rd**: “Oh When the Saints”\n- **Perfect 4th**: “Here Comes the Bride” or “Amazing Grace”\n- **Perfect 5th**: “Twinkle Twinkle Little Star”, 2nd to 3rd note\n- **Major 6th**: “My Bonnie Lies over the Ocean”\n- **Octave**: “Somewhere over the Rainbow”'] },
    { t: 'staff', h: 'Each interval from C', music: 'C4q Db4q rh | C4q D4q rh | C4q Eb4q rh | C4q E4q rh | C4q F4q rh | C4q G4q rh | C4q A4q rh | C4q C5q rh', p: ['The same eight intervals, all starting on C: minor 2nd, major 2nd, minor 3rd, major 3rd, perfect 4th, perfect 5th, major 6th and octave. Play each one and sing the matching song.'] },
    { t: 'text', h: 'Sing them', p: ['Hearing is good; singing is better. Choose a comfortable starting note, sing the first two notes of a song, then sing just the interval on “la”. Once that’s easy, try singing an interval before you think of the song.', 'Check yourself with the staff above, or next time you’re at the piano.'] },
    { t: 'tip', h: 'Going down', p: ['For falling intervals, sing a song’s first two notes, then sing them backwards, top note first. With practice, the falling sound becomes just as familiar as the rising one.'] },
    { t: 'quiz', q: 'The first two notes of “Here Comes the Bride” make which interval?', opts: ['Perfect 4th', 'Perfect 5th', 'Major 3rd'], ans: 0, why: '“Here Comes the Bride” opens with a rising perfect 4th, 5 {semis}, like C up to F. “Amazing Grace” starts with the same interval.' },
    { t: 'quiz', q: 'Which song starts with a rising **major 6th**?', opts: ['“My Bonnie Lies over the Ocean”', '“Greensleeves”', '“Frère Jacques”'], ans: 0, why: '“My Bonnie” leaps up a major 6th, 9 {semis}, like C up to A. “Greensleeves” starts with a minor 3rd, and “Frère Jacques” with a major 2nd.' },
    { t: 'quiz', q: 'In “Twinkle Twinkle Little Star”, which interval comes between the 2nd and 3rd notes?', opts: ['Perfect 5th', 'Octave', 'Perfect 4th'], ans: 0, why: 'The first two notes are the same (“Twin-kle”), then the next “twin” jumps up a perfect 5th, 7 {semis}, like C up to G.' },
    { t: 'task', h: 'Try this now', steps: ['Sing or hum the first two notes of each reference song in turn, from the minor 2nd up to the octave.', 'Choose a starting note and sing up a major 3rd, a perfect 5th and an octave, thinking of the matching songs.', 'Listen for intervals in everyday sounds, such as doorbells, ringtones and birdsong, and try to name each one.', 'Make your own list, adding songs you know well for any intervals you find hard.'] },
    { t: 'drill', h: 'Name the interval by ear (headphones on)', spec: { k: 'ear', mode: 'interval', set: [2, 3, 4, 5, 8], count: 8 } },
  ] },
  { id: 'th-transpose', u: 8, title: 'Transposing: moving music to a new key', mins: 7, sum: 'How to move a tune and its chords into a new key on paper, and why musicians do it all the time.', cards: [
    { t: 'text', h: 'Same song, new key', p: ['**Transposing** means moving a whole piece up or down by the same interval, into a new key. Every note moves together, so the tune and its chords sound the same, just higher or lower.', 'Why bother? To fit a singer’s range, to play along with another instrument, or to move a piece into a key that’s easier to play.'] },
    { t: 'text', h: 'Three steps', p: ['- **Choose the interval.** From C major to D major is up a major 2nd; from C to G is up a perfect 5th.\n- **Change the key signature** to the new key’s: D major has two sharps, F♯ and C♯.\n- **Move every note** by that interval, letter by letter. The key signature takes care of the sharps and flats.', 'Then check: the tune should start and end on the same scale degrees as before.'] },
    { t: 'staff', h: '“Mary Had a Little Lamb” in C', music: 'E4q D4q C4q D4q | E4q E4q E4h', p: ['The opening in C major: E D C D E E E, starting on the 3rd note of the scale.'] },
    { t: 'staff', h: 'The same tune in D', key: 'D', music: 'F#4q E4q D4q E4q | F#4q F#4q F#4h', p: ['Moved up a major 2nd, every note goes up one letter: E to F♯, D to E, C to D. The key signature’s two sharps turn every F into F♯, so no extra sharps are needed, and the tune still starts on the 3rd note.'] },
    { t: 'text', h: 'Transposing chords', p: ['Chords move the same way: transpose each root and keep the chord type. Easier still, think in **Roman numerals**, which don’t change. I–IV–V is C–F–G in C, **G–C–D** in G and **D–G–A** in D.', 'A minor chord stays minor and a 7th stays a 7th: Am7 in C major becomes Em7 in G.'] },
    { t: 'quiz', q: 'Transpose **C–Am–F–G** from C major to G major.', opts: ['G–Em–C–D', 'G–E–C–D', 'D–Bm–G–A'], ans: 0, why: 'As numerals it’s I–vi–IV–V. In G major, I is G, vi is Em, IV is C and V is D.' },
    { t: 'quiz', q: 'A tune in C major is moved up a perfect 5th. What is the new key?', opts: ['G major', 'F major', 'D major'], ans: 0, why: 'C up a perfect 5th (C D E F G) is G, so the tune lands in G major, with one sharp: F♯.' },
    { t: 'quiz', q: 'A melody note in C major is E. Moved to F major, which note does it become?', opts: ['A', 'A♭', 'B♭'], ans: 0, why: 'C up to F is a perfect 4th, so every note moves up a 4th. E up a 4th (E F G A) is A, the 3rd note of F major, just as E was the 3rd of C.' },
    { t: 'task', h: 'Try this now', steps: ['Write the opening of “Mary Had a Little Lamb” in C: E D C D E E E.', 'Transpose it to G major (up a perfect 5th) and to F major (up a perfect 4th), moving each note the same number of letters.', 'Check: in G it’s B A G A B B B; in F it’s A G F G A A A.', 'Transpose the chords I–V–vi–IV into D major and B♭ major. Check: D–A–Bm–G and B♭–F–Gm–E♭.', 'Next time you’re at the piano, play your versions and listen: the same tune, in a new place.'] },
    { t: 'drill', h: 'Chords in any key', spec: { k: 'roman', keys: ['C', 'G', 'D', 'F'], count: 8 } },
  ] },
);
